  transactions:[{id:'TXN-2026-1084',loanId:'LN-2026-0042',memberId:'M-2024-0186',memberName:'Miguel Santos',date:'2026-10-15',amount:5000,method:'Salary deduction',status:'Posted'},{id:'TXN-2026-1085',loanId:'LN-2026-0078',memberId:'M-2024-0186',memberName:'Miguel Santos',date:'2026-10-15',amount:1225,method:'Salary deduction',status:'Posted'},{id:'TXN-2026-1024',loanId:'LN-2026-0042',memberId:'M-2024-0186',memberName:'Miguel Santos',date:'2026-09-30',amount:5000,method:'Salary deduction',status:'Posted'},{id:'TXN-2026-1025',loanId:'LN-2026-0078',memberId:'M-2024-0186',memberName:'Miguel Santos',date:'2026-09-30',amount:1225,method:'Salary deduction',status:'Posted'},{id:'TXN-2026-0980',loanId:'LN-2026-0042',memberId:'M-2024-0186',memberName:'Miguel Santos',date:'2026-09-15',amount:5000,method:'Salary deduction',status:'Posted'}],
  members:[{id:'M-2024-0186',name:'Miguel Santos',initials:'MS',email:'miguel.santos@senate.gov.ph',department:'Legislative Services',status:'Verified',savings:62500,income:42000,age:32,joined:'March 12, 2024',phone:'+63 917 555 0186'},{id:'M-2023-0094',name:'Andrea Mendoza',initials:'AM',email:'andrea.mendoza@senate.gov.ph',department:'Administrative Services',status:'Verified',savings:85000,income:58000},{id:'M-2025-0210',name:'Carlo Villanueva',initials:'CV',email:'carlo.villanueva@senate.gov.ph',department:'Office of the Secretary',status:'Pending',savings:15000,income:32000},{id:'M-2022-0045',name:'Isabella Reyes',initials:'IR',email:'isabella.reyes@senate.gov.ph',department:'Finance Services',status:'Verified',savings:70000,income:49000}],
  users:[{id:'U-001',name:'Daniel Cruz',email:'admin@semco.demo',role:'Admin',status:'Active'},{id:'U-002',name:'Sofia Reyes',email:'staff@semco.demo',role:'Staff',status:'Active'},{id:'U-003',name:'Miguel Santos',email:'member@semco.demo',role:'Member',status:'Active'}],
