let state;try{const cached=JSON.parse(localStorage.getItem('semco-prototype-v1'));state=cached?.version===1?cached:seed();}catch{state=seed();}
let view=location.hash.slice(1)||state.view||'overview';let authStage='login',authRole='member',attempts=0,authName='',pendingRegistration=null,loginMemberId=null;
function operatorProfile(role){state.profileOverrides??={};return state.profileOverrides[role]??=(role==='staff'?{name:'Sofia Reyes',initials:'SR',email:'staff@semco.demo',department:'Loan Operations',id:'STAFF-002',status:'Active'}:{name:'Daniel Cruz',initials:'DC',email:'admin@semco.demo',department:'System Administration',id:'ADMIN-001',status:'Active'});}
const profiles={member:()=>state.members.find(m=>m.id===state.currentMemberId)||state.members[0],staff:()=>operatorProfile('staff'),admin:()=>operatorProfile('admin')};
const navs={member:[['overview','grid','Overview'],['applications','document','My applications'],['loans','wallet','My loans'],['payments','receipt','Payments & ledger'],['calculator','chart','Loan calculator']],staff:[['overview','grid','Overview'],['applications','document','Loan applications'],['verification','shield','Member verification'],['evaluation','activity','Credit evaluation'],['members','users','Member directory'],['ledger','wallet','Payments & ledger'],['reports','chart','Reports']],admin:[['overview','grid','Overview'],['users','users','Users & access'],['products','briefcase','Loan products'],['configuration','settings','Configuration'],['audit','history','Audit logs'],['reports','chart','Reports']]};
const titles={overview:'Overview',applications:'Loan applications',loans:'My loans',payments:'Payments & ledger',calculator:'Loan calculator',apply:'New application',profile:'My profile',search:'Record search',help:'Help & accessibility',verification:'Member verification',evaluation:'Credit evaluation',members:'Member directory',ledger:'Payments & ledger',reports:'Reports',users:'Users & access',products:'Loan products',configuration:'Configuration',audit:'Audit logs'};
function save(){try{localStorage.setItem('semco-prototype-v1',JSON.stringify(state));}catch{toast('Your browser could not save this demo session.');}}
function addAudit(action,details){state.audit.unshift({id:'AUD-'+Date.now(),date:new Date().toLocaleString('sv-SE',{timeZone:'Asia/Manila'}).replace(' ','T'),actor:profiles[state.role]().name,action,details});save();}
function navigate(next){view=next;state.view=next;location.hash=next;save();render();window.scrollTo(0,0);document.querySelector('#main-content')?.focus({preventScroll:true});}
function toast(message){const el=document.createElement('div');el.className='app-toast';el.innerHTML=icon('check-circle')+`<span>${esc(message)}</span>`;document.querySelector('#toast-region').append(el);setTimeout(()=>el.remove(),5200);}
let previousFocus;
function closeModal(){document.querySelector('#modal-root').innerHTML='';document.body.style.overflow='';previousFocus?.focus();}
function openModal(title,body,footer=''){previousFocus=document.activeElement;document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop-custom"><section class="app-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-close-modal aria-label="Close dialog">${icon('x')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';document.querySelector('[data-close-modal]').onclick=closeModal;document.querySelector('.modal-backdrop-custom').onclick=e=>{if(e.target===e.currentTarget)closeModal();};document.querySelector('#modal-root button, #modal-root input')?.focus();}
const ctx=()=>({state,member:profiles.member(),currentProfile:profiles[state.role](),products,save,render,navigate,toast,openModal,closeModal,addAudit});
function brand(){return `<div class="brand"><span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i><i></i></span><div class="brand-name">SEMCO<small>Your cooperative, connected.</small></div></div>`;}
function render(){document.body.classList.toggle('high-contrast',state.preferences.contrast);document.body.classList.toggle('large-text',state.preferences.largeText);if(!state.authenticated){renderAuth();return;}
  const role=state.role,p=profiles[role]();const valid=[...navs[role].map(n=>n[0]),'profile','help','search',...(role==='member'?['apply']:[])];if(!valid.includes(view))view='overview';
  document.title=`${titles[view]||'Overview'} · SEMCO`;
  document.querySelector('#app').innerHTML=`<div class="app-shell"><div class="sidebar-overlay" id="sidebar-overlay"></div><aside class="sidebar" id="main-navigation" aria-label="Main navigation">${brand()}<div class="nav-label">${role==='member'?'Your workspace':role==='staff'?'Operations':'Administration'}</div><nav class="side-nav">${navs[role].map(([id,i,label])=>`<button class="nav-item ${view===id?'active':''}" data-nav="${id}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='applications'?`<span class="nav-count">${state.applications.filter(a=>a.status==='Pending'&&(role!=='member'||a.memberId===p.id)).length}</span>`:''}</button>`).join('')}</nav><div class="nav-label">Account</div><nav class="side-nav"><button class="nav-item ${view==='search'?'active':''}" data-nav="search">${icon('search')}Record search</button><button class="nav-item ${view==='profile'?'active':''}" data-nav="profile">${icon('user')}My profile</button><button class="nav-item ${view==='help'?'active':''}" data-nav="help">${icon('help')}Help & accessibility</button></nav><div class="sidebar-bottom"><div class="support-card">${icon('leaf')}<h4>Here for your next step.</h4><p>A little support can make a big difference. We're here to help.</p><button data-nav="help">Talk to your cooperative ${icon('arrow-up-right')}</button></div><div class="sidebar-profile"><span class="avatar peach">${esc(p.initials)}</span><div><strong>${esc(p.name)}</strong><small>${role.charAt(0).toUpperCase()+role.slice(1)} account</small></div><button class="profile-logout" data-action="logout" title="Sign out of demo" aria-label="Sign out">${icon('logout')}</button></div></div></aside><div class="workspace"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation" aria-controls="main-navigation" aria-expanded="false">${icon('menu')}</button><div class="breadcrumbs">${role.charAt(0).toUpperCase()+role.slice(1)} portal ${icon('chevron-right')}<strong>${titles[view]||'Overview'}</strong></div><div class="topbar-right"><span class="topbar-date">${new Date().toLocaleDateString('en-PH',{timeZone:'Asia/Manila',weekday:'long',month:'long',day:'numeric',year:'numeric'})}</span><div class="role-switch"><label for="role-switch">Preview as</label><select id="role-switch" aria-label="Preview role"><option value="member" ${role==='member'?'selected':''}>Member</option><option value="staff" ${role==='staff'?'selected':''}>Staff</option><option value="admin" ${role==='admin'?'selected':''}>Admin</option></select></div><button class="icon-btn topbar-search" data-action="search" aria-label="Search records">${icon('search')}</button><span class="topbar-divider"></span><button class="icon-btn topbar-bell" data-action="notifications" aria-label="View notifications">${icon('bell')}<i class="notification-dot"></i></button><button class="avatar peach topbar-avatar border-0" data-nav="profile" aria-label="View profile">${esc(p.initials)}</button></div></header><main id="main-content" class="main-content" tabindex="-1">${view==='profile'?profilePage(p):view==='search'?renderRecordSearch(ctx()):view==='help'?helpPage():role==='member'?renderMember(view,ctx()):role==='staff'?renderStaff(view,ctx()):renderAdmin(view,ctx())}<footer class="page-footer"><span>© 2026 Senate Employees Multipurpose Cooperative</span><span><i class="prototype-dot"></i>Prototype · Fictional records & sample policies</span></footer></main></div></div>`;
  document.querySelector('#role-switch').onchange=e=>{state.role=e.target.value;view='overview';state.view=view;location.hash=view;save();render();};
  document.querySelector('#sidebar-overlay').onclick=()=>{document.querySelector('.sidebar').classList.remove('open');document.querySelector('#sidebar-overlay').classList.remove('show');syncSidebarState();};syncSidebarState();
  if(view==='profile')bindProfileForm(p,ctx());else if(view==='search')bindRecordSearch(ctx());else if(role==='member')bindMember(view,ctx());else bindOperators(role,view,ctx());bindHelp();
}
function profilePage(p){return renderProfileForm(p,ctx());}
function helpPage(){return pageHeading('A helping hand','How can we help?','A few useful answers, and a portal that works for you.')+`<div class="content-grid"><section class="panel"><div class="panel-head"><h2>Frequently asked questions</h2>${icon('help')}</div><div class="panel-body">${[
['How do I apply for a loan?','Choose New application, select a loan facility, enter your loan and financial details, then review and submit. Staff verify your information before the advisory evaluation and final review.'],
['How can I track my application?','Open My applications and select Track application. You can follow submission, staff verification, credit evaluation, and the Chairman or Vice Chairman’s decision.'],
['Can I change a submitted application?','Pending applications and applications returned for revision can be edited. Once verification starts, contact your cooperative for changes.'],
['How are my payments collected?','Payments use internal salary deductions. Staff can also record over-the-counter payments for special cases. This portal does not accept online payments.'],
['Does my evaluation score approve my loan?','No. The simplified SEMCO Credit Evaluation Algorithm provides an advisory recommendation using a Belief Rule Base. The final decision remains with the Chairman or Vice Chairman.'],
['Which features are part of this prototype?','Explore all three roles, create applications, run sample evaluations, verify records, simulate final decisions, and change demo settings. Registration, loan applications, profile changes, and record search include validation and saved results. PDF downloads, production authentication, and file storage remain outside this prototype.']
].map(([q,a])=>`<details class="faq-item"><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section><div><section class="panel"><div class="panel-head"><h2>Make yourself comfortable</h2>${icon('settings')}</div><div class="panel-body"><div class="setting-row"><div><strong>Higher contrast</strong><p>Improve text and border visibility.</p></div><div class="form-check form-switch"><input class="form-check-input" type="checkbox" role="switch" id="contrast-toggle" aria-label="Higher contrast" ${state.preferences.contrast?'checked':''}></div></div><div class="setting-row"><div><strong>Larger text</strong><p>Give the words a little more room.</p></div><div class="form-check form-switch"><input class="form-check-input" type="checkbox" role="switch" id="text-toggle" aria-label="Larger text" ${state.preferences.largeText?'checked':''}></div></div></div></section><section class="panel"><div class="panel-body"><span class="stat-icon mb-3">${icon('mail')}</span><h3 class="section-title mb-2">Your cooperative is here.</h3><p class="muted text-small" style="line-height:1.8">For account or loan concerns, visit the SEMCO office at the Senate. This prototype does not send messages.</p><button class="btn btn-light w-100" data-action="manual">${icon('document')} View quick-start guide</button></div></section><button class="btn btn-link" data-action="reset">Reset demo data ${icon('history')}</button></div></div>`;}
function bindHelp(){const a=document.querySelector('#contrast-toggle'),b=document.querySelector('#text-toggle');if(a)a.onchange=e=>{state.preferences.contrast=e.target.checked;save();render();};if(b)b.onchange=e=>{state.preferences.largeText=e.target.checked;save();render();};}
function renderAuth(){const labels={member:'Member',staff:'Staff',admin:'Admin'};document.querySelector('#app').innerHTML=`<div class="auth-screen ${authStage==='register'?'registration-screen':''}"><section class="auth-story">${brand()}<div><div class="hero-kicker">Together, we move forward.</div><h1>Your cooperative.<br>Your next chapter.</h1><p>A simpler, more connected way to manage your loans and build a little more possibility.</p></div><div class="auth-story-footer">Senate Employees Multipurpose Cooperative<br><br>Serving our members since 1991.</div></section><main class="auth-form-side"><div class="auth-form-wrap ${authStage==='register'?'registration-wrap':''}">${authStage==='otp'?`<span class="stat-icon mb-4">${icon('shield')}</span><h2>One more step.</h2><p>Enter the six-digit code for your demo account.</p><form id="otp-form"><label class="form-label" for="otp">Verification code</label><input id="otp" class="form-control otp-input" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required autofocus><div class="auth-note">Demo code: <strong>123456</strong><br>No email is sent. You have ${3-attempts} attempts remaining.</div><button class="btn btn-primary w-100" type="submit">Verify & continue ${icon('arrow-right')}</button><p class="text-center mt-3"><button type="button" class="btn-link" id="resend-otp">Resend demo code</button></p></form>`:authStage==='register'?`${renderRegistration()}`:`<h2>Welcome back.</h2><p>A little closer to what comes next. Sign in to SEMCO.</p><div class="auth-role-list">${Object.entries(labels).map(([id,label])=>`<button data-auth-role="${id}" class="${authRole===id?'active':''}">${label}</button>`).join('')}</div><form id="login-form"><div class="field"><label class="form-label" for="email">Email address</label><input class="form-control" type="email" id="email" required value="${authRole}@semco.demo" autocomplete="username"></div><div class="field"><label class="form-label" for="password">Password</label><input class="form-control" type="password" id="password" minlength="8" required value="semco123" autocomplete="current-password"></div><button class="btn btn-primary w-100" type="submit">Sign in ${icon('arrow-right')}</button><div class="auth-note">Interactive prototype · use <strong>${authRole}@semco.demo</strong> and <strong>semco123</strong>. Authentication and OTP are simulated.</div></form><p class="registration-link">New to SEMCO? <button id="show-register">Create a member account</button></p>`}</div></main></div>`;
 document.querySelectorAll('[data-auth-role]').forEach(b=>b.onclick=()=>{authRole=b.dataset.authRole;renderAuth();});
 const login=document.querySelector('#login-form');if(login)login.onsubmit=async e=>{e.preventDefault();const email=document.querySelector('#email').value.trim().toLowerCase(),password=document.querySelector('#password').value;const registered=authRole==='member'?state.members.find(m=>m.email.toLowerCase()===email&&m.demoCredential):null;const validDemo=email===`${authRole}@semco.demo`&&password==='semco123';const validRegistered=registered&&await verifyDemoCredential(password,registered.demoCredential);if(!validDemo&&!validRegistered){toast('Check your email and password, or use the sample credentials below.');return;}loginMemberId=validRegistered?registered.id:'M-2024-0186';pendingRegistration=null;authStage='otp';attempts=0;authName='';renderAuth();};
 if(authStage==='register')bindRegistration({state,save,toast,onRegistered:member=>{pendingRegistration=member;authName=member.name;authRole='member';authStage='otp';attempts=0;renderAuth();toast('Registration validated. Complete the demo verification to save your account.');}});
 const otp=document.querySelector('#otp-form');if(otp)otp.onsubmit=e=>{e.preventDefault();if(document.querySelector('#otp').value!=='123456'){attempts++;if(attempts>=3){authStage='login';toast('Attempt limit reached. Start the demo sign-in again.');}else toast('Incorrect code. Use the demo code 123456.');renderAuth();return;}state.role=authRole;state.authenticated=true;if(pendingRegistration){state.members.push(pendingRegistration);state.users.push({id:'U-'+Date.now(),name:pendingRegistration.name,email:pendingRegistration.email,role:'Member',status:'Active',memberId:pendingRegistration.id});state.currentMemberId=pendingRegistration.id;pendingRegistration=null;addAudit('Member registered','Validated demo membership form saved');}else state.currentMemberId=loginMemberId||'M-2024-0186';authStage='login';addAudit('Demo sign-in','Simulated OTP verified');view='overview';save();render();};
 const resend=document.querySelector('#resend-otp');if(resend)resend.onclick=()=>{attempts=0;renderAuth();toast('Demo code reset: 123456. No email was sent.');};
 const sr=document.querySelector('#show-register');if(sr)sr.onclick=()=>{pendingRegistration=null;authStage='register';renderAuth();};const bl=document.querySelector('#back-login');if(bl)bl.onclick=()=>{pendingRegistration=null;authStage='login';renderAuth();};
}
document.addEventListener('click',e=>{if(e.target.closest('.skip-link')){e.preventDefault();document.querySelector('#main-content')?.focus();return;}if(e.target.closest('[data-close-modal]')){closeModal();return;}const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}const a=e.target.closest('[data-action]')?.dataset.action;if(!a)return;
 if(a==='prototype')toast('PDF export is presentation only in this prototype.');
 if(a==='menu'){document.querySelector('.sidebar').classList.toggle('open');document.querySelector('#sidebar-overlay').classList.toggle('show');syncSidebarState();}
 if(a==='logout'){state.authenticated=false;authStage='login';authRole=state.role;save();render();}
 if(a==='notifications')openModal('Your updates',`<div class="activity-item"><span class="activity-icon">${icon('document')}</span><div><strong>Application received</strong><p>Your Economic loan application is waiting for staff verification.</p></div></div><div class="activity-item"><span class="activity-icon">${icon('calendar')}</span><div><strong>Your next payment is October 30</strong><p>Your regular salary deduction will be reflected in your ledger.</p></div></div>`);
 if(a==='search')navigate('search');
 if(a==='manual')openModal('Your quick-start guide',`<ol class="text-small" style="line-height:2.2"><li>Use <strong>Preview as</strong> to switch between member, staff, and admin.</li><li>As a member, submit a new application or view your loans and ledger.</li><li>As staff, verify the application, run credit evaluation, then simulate a Chairman/Vice Chairman decision.</li><li>As admin, manage demo users, inspect products, update sample rates, and review the activity log.</li><li>All changes stay in this browser. Use Reset demo data to start again.</li></ol>`);
 if(a==='reset'){openModal('Start with a fresh demo?',`<p>This resets the fictional applications, evaluations, accounts, and settings saved in this browser.</p>`,`<button class="btn btn-light" id="cancel-reset">Keep my changes</button><button class="btn btn-primary" id="confirm-reset">Reset demo</button>`);document.querySelector('#cancel-reset').onclick=closeModal;document.querySelector('#confirm-reset').onclick=()=>{state=seed();view='overview';save();closeModal();render();toast('Demo reset. You’re back in the member portal.');};}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&document.querySelector('.app-modal')){const focusable=[...document.querySelectorAll('.app-modal button,.app-modal input,.app-modal select,.app-modal textarea,.app-modal a')].filter(el=>!el.disabled);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
function syncSidebarState(){const side=document.querySelector('.sidebar');if(!side)return;const mobile=matchMedia('(max-width:767px)').matches;const open=side.classList.contains('open');side.inert=mobile&&!open;side.setAttribute('aria-hidden',String(mobile&&!open));document.querySelector('[data-action="menu"]')?.setAttribute('aria-expanded',String(open));}
window.addEventListener('resize',syncSidebarState);
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'overview';if(view!==next){view=next;render();}});
render();
